template <typename T>
inline std::optional<T> get_ordinal_table_entry(std::shared_ptr<OrdinalTable<T>> table, double ordinal) {
  if (((!flight::is_integer(ordinal) || (ordinal < 0.0)) || (ordinal >= static_cast<double>(table->entries.size())))) {
    return std::nullopt;
  }
  return table->entries.element(ordinal);
}


